package br.com.archlab.simulation.core.v3;
import java.util.*;import static br.com.archlab.simulation.core.v3.ArchitectureV3.*;
/** Runtime admission for the finite initial catalog. No execution occurs during validation. */
public final class ScenarioValidatorV3 {
    private final TypeCatalogV3 catalog=TypeCatalogV3.initial();
    public ValidationResultV3 architecture(ArchitectureV3 a){var errors=new ArrayList<>(new ArchitectureValidatorV3(catalog).validate(a).violations());for(var plan:a.executionPlans())errors.addAll(new ExecutionPlanValidatorV3(catalog).validate(a,plan).violations());
        for(int i=0;i<a.components().size();i++)ranges(a.components().get(i).properties(),"/components/"+i+"/properties",errors);
        for(int i=0;i<a.relations().size();i++){var relation=a.relations().get(i);ranges(relation instanceof Communication c?c.properties():((Structural)relation).properties(),"/relations/"+i+"/properties",errors);}
        for(int i=0;i<a.resources().size();i++){var r=a.resources().get(i);String path="/resources/"+i+"/properties";ranges(r.properties(),path,errors);
            for(String key:List.of("consumerConcurrency","maxDeliveryAttempts","maxAttempts"))if(r.properties().get(key) instanceof PropertyValueV3.IntegerValue n && (n.value()<1 || n.value()>100_000))error(errors,"PROPERTY_RANGE",path+"/"+key,r.id());
            if(r.typeId().value().equals("MESSAGE_QUEUE")){var consumer=r.properties().get("consumerEndpointId");var endpoint=consumer instanceof PropertyValueV3.Reference ref?a.endpoints().stream().filter(e->e.id().equals(ref.targetId())).findFirst():Optional.<Endpoint>empty();if(endpoint.isEmpty() || endpoint.get().direction()==Direction.OUTBOUND || endpoint.get().operationIds().isEmpty())error(errors,"QUEUE_CONSUMER_REQUIRED",path+"/consumerEndpointId",r.id());
                if(r.properties().get("consumerOperationId") instanceof PropertyValueV3.Reference ref && endpoint.isPresent() && !endpoint.get().operationIds().contains(ref.targetId()))error(errors,"QUEUE_CONSUMER_OPERATION",path+"/consumerOperationId",r.id());}
            if(r.typeId().value().equals("TOPIC")){var queues=r.properties().get("queueIds");var seen=new HashSet<IdentifierV3>();if(!(queues instanceof PropertyValueV3.Values list) || list.values().isEmpty())error(errors,"TOPIC_QUEUES_REQUIRED",path+"/queueIds",r.id());else for(var value:list.values())if(!(value instanceof PropertyValueV3.Reference ref) || !seen.add(ref.targetId()) || a.resources().stream().noneMatch(q->q.id().equals(ref.targetId()) && q.typeId().value().equals("MESSAGE_QUEUE")))error(errors,"TOPIC_QUEUE_INVALID",path+"/queueIds",r.id());}
        }
        return new ValidationResultV3(errors);}
    public ValidationResultV3 validate(SimulationRequestV3 request){var a=request.architecture();var errors=new ArrayList<ViolationV3>();for(var v:architecture(a).violations())errors.add(new ViolationV3(v.code(),"/architecture"+v.path(),v.message(),v.severity(),v.relatedIds()));
        for(var v:new ArchitectureValidatorV3(catalog).validateInitialState(a,request.scenario().initialStates()).violations())errors.add(new ViolationV3(v.code(),v.path().replace("/initialState/","/scenario/initialStates/"),v.message(),v.severity(),v.relatedIds()));var entry=request.scenario().entry();var initiator=a.components().stream().filter(c->c.id().equals(entry.componentId())).findFirst();if(initiator.isEmpty())error(errors,"ENTRY_COMPONENT_NOT_FOUND","/scenario/entry/componentId",entry.componentId());else if(!initiator.get().typeId().value().equals("CLIENT_GENERIC"))error(errors,"ENTRY_INITIATOR_TYPE","/scenario/entry/componentId",entry.componentId());
        var operation=a.operations().stream().filter(o->o.id().equals(entry.operationId())).findFirst();if(operation.isEmpty())error(errors,"ENTRY_OPERATION_NOT_FOUND","/scenario/entry/operationId",entry.operationId());
        if(entry.connectionId()!=null){var connection=a.relations().stream().filter(r->r.id().equals(entry.connectionId()) && r instanceof Communication).map(r->(Communication)r).findFirst();if(connection.isEmpty())error(errors,"ENTRY_CONNECTION_NOT_FOUND","/scenario/entry/connectionId",entry.connectionId());else{var c=connection.get();var source=a.endpoints().stream().filter(e->e.id().equals(c.sourceEndpointId())).findFirst();var target=a.endpoints().stream().filter(e->e.id().equals(c.targetEndpointId())).findFirst();if(source.isEmpty() || !source.get().ownerId().equals(entry.componentId()) || target.isEmpty() || !target.get().operationIds().contains(entry.operationId()))error(errors,"ENTRY_CONNECTION_MISMATCH","/scenario/entry/connectionId",entry.connectionId());}}
        for(int i=0;i<request.scenario().initialStates().size();i++){var state=request.scenario().initialStates().get(i);if(state instanceof InitialStateV3.Policy policy && policy.state()!=null && !Set.of("ENABLED","DISABLED").contains(policy.state()))error(errors,"POLICY_STATE_NOT_SUPPORTED","/scenario/initialStates/"+i+"/state",policy.policyInstanceId());if(state instanceof InitialStateV3.Queue q && q.initialMessageCount()!=null && (q.initialMessageCount()<0 || q.initialMessageCount()>1000))error(errors,"INITIAL_QUEUE_RANGE","/scenario/initialStates/"+i+"/initialMessageCount",q.queueId());}
        if(request.options().horizonAtMs()!=null && request.options().horizonAtMs()>1_000_000_000_000L)error(errors,"HORIZON_RANGE","/options/horizonAtMs");return new ValidationResultV3(errors);}
    private static void ranges(Map<String,PropertyValueV3> values,String path,List<ViolationV3> errors){for(var e:new TreeMap<>(values).entrySet())if(e.getValue() instanceof PropertyValueV3.IntegerValue n && (n.value()<0 || n.value()>1_000_000_000_000L))error(errors,"PROPERTY_RANGE",path+"/"+e.getKey());}
    private static void error(List<ViolationV3> errors,String code,String path,IdentifierV3... ids){errors.add(new ViolationV3(code,path,code,ViolationV3.Severity.ERROR,List.of(ids)));}
}
